package com.audiobookdownloader;
import org.jsoup.*;import org.jsoup.nodes.*;import java.util.*;
/** UUID routes are classified only by their own explicit metadata, never by the URL shape alone. */
public final class KnigobludSeriesParser {
 public static final class Detail {public final String title,author,series,url;public final List<ContinuationRules.Book> books;Detail(String t,String a,String s,String u,List<ContinuationRules.Book>b){title=t;author=a;series=s;url=u;books=b;}}
 private static String text(Element e,String sel){Element n=e.selectFirst(sel);return n==null?"":n.text();}
 private static String writer(Element root){for(Element m:root.select(".bookListItemMetaBlock,.BookDetailsItem,.BookMetaBlockLine,.BookDescriptionLabel"))if(m.text().contains("✍")){Element a=m.selectFirst("a[href]");if(a!=null)return a.text();}return "";}
 public static List<ContinuationRules.Book> search(String html,String url){Document d=Jsoup.parse(html,url);List<ContinuationRules.Book> out=new ArrayList<>();for(Element card:d.select(".bookListItem")){Element a=card.selectFirst("a.bookListItemCover[href]");if(a==null)continue;String title=text(card,".bookListItemCoverNameText");String address=a.absUrl("href");if(valid(address)&&!title.isEmpty())out.add(new ContinuationRules.Book(title,address,writer(card),ContinuationRules.order(title)));}return out;}
 public static boolean valid(String url){return url!=null&&url.matches("https://(?:(?:www|mob)\\.)?knigoblud\\.club/[a-fA-F0-9-]{36}/?");}
 public static boolean sameCycle(String a,String b){return valid(a)&&valid(b)&&java.net.URI.create(a).getPath().replaceAll("/+$","").equals(java.net.URI.create(b).getPath().replaceAll("/+$",""));}
 public static Detail detail(String html,String url){if(!valid(url))throw new IllegalArgumentException("Не страница Книгоблуда");Document d=Jsoup.parse(html,url);Element box=d.selectFirst(".BookDescription.BookSeries");if(box==null)throw new IllegalArgumentException("Источник не указал список цикла");Element cycle=box.selectFirst(".BookDescriptionLabel a[href]");if(cycle==null||!valid(cycle.absUrl("href"))||cycle.absUrl("href").equals(url))throw new IllegalArgumentException("Нет ссылки на цикл");List<ContinuationRules.Book> books=new ArrayList<>();String author=writer(d);for(Element a:box.select("a.BookDescriptionSeriesItem[href]")){String name=text(a,".BookDescriptionSeriesItemName,b");if(name.isEmpty()||!valid(a.absUrl("href")))continue;Double order=null;try{order=Double.valueOf(text(a,".BookDescriptionSeriesItemIndex").replaceFirst("[.)]$","").trim());}catch(Exception ignored){}books.add(new ContinuationRules.Book(name,a.absUrl("href"),author,order));}if(books.isEmpty()||books.size()>100)throw new IllegalArgumentException("Неполный список цикла");return new Detail(text(d,"h1"),author,cycle.text(),cycle.absUrl("href"),books);}
}
